// 记录过去30天到数据到excel
func InitExcelOnce() {
	go func() {
		ctx := context.Background()
		timeStart := time.Now().Add(-7 * 24 * time.Hour)
		for i := 0; i < 7; i++ {
			link_trace.RecordExcel(ctx, timeStart.Add(time.Duration(i)*24*time.Hour))
		}
		hlog.CtxInfof(ctx, "init excel once success")
	}()
}

